style.css:
@-moz-document domain("youtube.com") {
/* MAIN BACKGROUND – dark pink gradient */
  body, ytd-app, #content, #page-manager {
    background: linear-gradient(135deg, #2a001f, #77003f) !important;
    color: #ffd6f5 !important;
  }

  /* HEADER / TOP BAR */
  ytd-masthead {
    background-color: #3d002b !important;
    border-bottom: 2px solid #ff0f8a !important;
  }

  /* SEARCH BAR */
  #search-input input {
    background-color: #4d0036 !important;
    color: #ffd6f5 !important;
    border: 1px solid #ff4fa6 !important;
  }
  #search-icon-legacy {
    background-color: #ff4fa6 !important;
  }

  /* SIDEBAR */
  ytd-guide-renderer {
    background-color: #330024 !important;
  }
  ytd-guide-entry-renderer:hover {
    background-color: #550036 !important;
  }

  /* VIDEO TITLES */
  #video-title {
    color: #ff4fa6 !important;
  }

  /* LINKS */
  a, .yt-simple-endpoint, yt-formatted-string {
    color: #ff79c9 !important;
  }

  /* SUBSCRIBE BUTTON */
  ytd-subscribe-button-renderer button {
    background-color: #ff0f8a !important;
    color: #fff !important;
    border-radius: 10px !important;
  }
  ytd-subscribe-button-renderer button:hover {
    background-color: #d40072 !important;
  }

  /* LIKE / SHARE BUTTONS */
  ytd-toggle-button-renderer button {
    background-color: #4d0036 !important;
    border: 1px solid #ff4fa6 !important;
    border-radius: 8px !important;
  }
  ytd-toggle-button-renderer button:hover {
    background-color: #77003f !important;
  }

  /* COMMENTS */
  #comments {
    background-color: #330024 !important;
  }
  #content-text {
    color: #ffb0df !important;
  }

  /* SPARKLES (floating subtle pink sparkles) */
  body::after {
    content: "";
    pointer-events: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-image:
      radial-gradient(circle, rgba(255,150,220,0.7) 2px, transparent 3px),
      radial-gradient(circle, rgba(255,100,200,0.6) 1px, transparent 3px),
      radial-gradient(circle, rgba(255,180,240,0.5) 2px, transparent 3px);
    background-size: 200px 200px, 150px 150px, 250px 250px;
    animation: sparkleMove 12s linear infinite;
    z-index: 999999;
  }

  @keyframes sparkleMove {
    0% {
      background-position: 0 0, 0 0, 0 0;
    }
    100% {
      background-position: 200px 1000px, 150px 800px, 250px 1200px;
    }
  }

  /* SCROLLBAR */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-thumb {
    background: #ff0f8a !important;
    border-radius: 8px;
  }
  ::-webkit-scrollbar-track {
    background: #330024 !important;
  }
}
